/**
 * We'll load the axios HTTP library which allows us to easily issue requests
 * to our Laravel back-end. This library automatically handles sending the
 * CSRF token as a header based on the value of the "XSRF" token cookie.
 */

window.axios = require("axios");

window.axios.defaults.headers.common["X-Requested-With"] = "XMLHttpRequest";
window.axios.defaults.baseUrl = "http://localhost:8000";

/**
 * Echo exposes an expressive API for subscribing to channels and listening
 * for events that are broadcast by Laravel. Echo and event broadcasting
 * allows your team to easily build robust real-time web applications.
 */

let echoInitError = null;
try {
  const Echo = require('laravel-echo');
  window.Pusher = require('pusher-js');
  const key = process.env.MIX_PUSHER_APP_KEY || process.env.PUSHER_APP_KEY;
  const cluster = process.env.MIX_PUSHER_APP_CLUSTER || process.env.PUSHER_APP_CLUSTER || 'mt1';
  const host = process.env.MIX_PUSHER_HOST || process.env.PUSHER_HOST;
  const port = parseInt(process.env.MIX_PUSHER_PORT || process.env.PUSHER_PORT || '443', 10);
  const scheme = (process.env.MIX_PUSHER_SCHEME || process.env.PUSHER_SCHEME || 'https');
  if (key) {
    window.Echo = new Echo({
      broadcaster: 'pusher',
      key,
      cluster,
      wsHost: host || undefined,
      wsPort: port,
      wssPort: port,
      forceTLS: scheme === 'https',
      enabledTransports: ['ws', 'wss'],
    });
  } else {
    window.Echo = null;
  }
} catch (e) {
  echoInitError = e;
  window.Echo = null;
}

// Dashboard notifications subscription
try {
  function initNotifications(){
    if (!window.Echo) return;
    const channel = window.Echo.channel('dashboard.notifications');
    channel.listen('.message.dispatched', function(ev){
      const list = document.getElementById('notificationsList');
      if (!list) return;
      const li = document.createElement('li');
      li.className = 'list-group-item d-flex align-items-start gap-2';
      const badge = document.createElement('span');
      badge.className = 'badge bg-' + (ev.type === 'sms' ? 'primary' : 'success');
      badge.textContent = ev.type.toUpperCase();
      const body = document.createElement('div');
      const text = document.createElement('div');
      text.textContent = ev.text || '';
      const meta = document.createElement('small');
      meta.className = 'text-muted';
      meta.textContent = (ev.fault_ref_number ? ('Fault ' + ev.fault_ref_number + ' • ') : '') + (ev.time || '');
      body.appendChild(text);
      body.appendChild(meta);
      li.appendChild(badge);
      li.appendChild(body);
      list.prepend(li);
      const countEl = document.getElementById('notificationsCount');
      if (countEl) {
        const n = parseInt(countEl.textContent || '0', 10) + 1;
        countEl.textContent = String(n);
        countEl.style.display = '';
      }
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initNotifications);
  } else {
    initNotifications();
  }
} catch (_) {}
